import { S3Client, PutObjectCommand } from '@aws-sdk/client-s3';
import { CloudFrontClient, CreateInvalidationCommand } from '@aws-sdk/client-cloudfront';
import { readFileSync, statSync } from 'fs';

const ACCESS_KEY = 'AKIASAJBIV7CECCECRRV';
const SECRET_KEY = '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';
const REGION = 'us-east-1';
const DIST_ID = 'E1C0DEI0VKCUYN';
const BUCKET = 'ivxholding.com';

const APK_PATH = '/home/user/rork-app/expo/android/app/build/outputs/apk/qa/app-qa.apk';
const S3_KEY = 'downloads/ivx-holdings-1.10.4-owner.apk';

const s3 = new S3Client({ region: REGION, credentials: { accessKeyId: ACCESS_KEY, secretAccessKey: SECRET_KEY } });
const cf = new CloudFrontClient({ region: 'us-east-1', credentials: { accessKeyId: ACCESS_KEY, secretAccessKey: SECRET_KEY } });

const size = statSync(APK_PATH).size;
console.log(`Uploading APK (${(size / 1024 / 1024).toFixed(1)} MB) to s3://${BUCKET}/${S3_KEY}`);

const body = readFileSync(APK_PATH);
await s3.send(new PutObjectCommand({
  Bucket: BUCKET,
  Key: S3_KEY,
  Body: body,
  ContentType: 'application/vnd.android.package-archive',
  ContentLength: size,
  ACL: 'public-read',
  CacheControl: 'no-cache, no-store, must-revalidate',
}));
console.log('S3 upload: SUCCESS');

// Invalidate CloudFront so the file is immediately available
try {
  await cf.send(new CreateInvalidationCommand({
    DistributionId: DIST_ID,
    InvalidationBatch: {
      CallerReference: `apk-upload-${Date.now()}`,
      Paths: { Quantity: 1, Items: [`/${S3_KEY}`] },
    },
  }));
  console.log('CloudFront invalidation: SUCCESS');
} catch (e) {
  console.log('CloudFront invalidation skipped: ' + e.message);
}

console.log('');
console.log('=== DOWNLOAD LINK ===');
console.log(`https://ivxholding.com/${S3_KEY}`);
console.log(`https://www.ivxholding.com/${S3_KEY}`);
EOF
bun run /tmp/upload-apk.mjs 2>&1

